challenge.verificationSource:
mod solution;

fn valid(input: &str, actual: &str, _expected: &str) -> bool {
    let values: Vec<i64> = input.trim().trim_start_matches('[').trim_end_matches(']').split(',').map(|x|x.trim().parse().unwrap()).collect();
    let Ok(i) = actual.parse::<usize>() else { return false; };
    i < values.len() && (i == 0 || values[i] > values[i-1]) && (i+1 == values.len() || values[i] > values[i+1])
}

fn main() {
    let cases = [
        ("[1,2,3,1]","2"),
        ("[3,2,1]","0"),
        ("[1,4,2]","1"),
        ("[1,2,3,4]","3"),
        ("[4,3,2,1]","0"),
        ("  \n[1,2,3,1]\n  ","2"),
        ("\n[4,3,2,1]\n","0")
    ];
    for (i,(input,expected)) in cases.iter().enumerate() {
        let actual = solution::solve(input);
        if !valid(input,&actual,expected) { eprintln!("PRIVATE CASE {} FAILED",i+1); std::process::exit(1); }
    }
    println!("PASS peak-search");
}
